class Arbitrary {
  constructor(generator) {
    this.generate = generator;
  }
  map(fn) {
    return new Arbitrary((mrng) => fn(this.generate(mrng)));
  }
  filter(fn) {
    return new Arbitrary((mrng) => {
      for (let i = 0; i < 100; i++) {
        const val = this.generate(mrng);
        if (fn(val)) return val;
      }
      return this.generate(mrng);
    });
  }
}

function randInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

export const fc = {
  string({ maxLength = 20 } = {}) {
    return new Arbitrary(() => {
      const len = randInt(0, maxLength);
      let s = '';
      const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,\n\t/:-';
      for (let i = 0; i < len; i++) s += chars[randInt(0, chars.length - 1)];
      return s;
    });
  },
  integer({ min = -1000, max = 1000 } = {}) {
    return new Arbitrary(() => randInt(min, max));
  },
  float({ min = 0, max = 1000, noNaN = true } = {}) {
    return new Arbitrary(() => Math.random() * (max - min) + min);
  },
  boolean() {
    return new Arbitrary(() => Math.random() > 0.5);
  },
  constant(val) {
    return new Arbitrary(() => val);
  },
  constantFrom(...values) {
    return new Arbitrary(() => values[randInt(0, values.length - 1)]);
  },
  option(arb, { nil = null } = {}) {
    return new Arbitrary(() => (Math.random() > 0.3 ? arb.generate() : nil));
  },
  oneof(...arbs) {
    return new Arbitrary(() => arbs[randInt(0, arbs.length - 1)].generate());
  },
  tuple(...arbs) {
    return new Arbitrary(() => arbs.map((a) => a.generate()));
  },
  array(arb, { maxLength = 10 } = {}) {
    return new Arbitrary(() => {
      const len = randInt(0, maxLength);
      const arr = [];
      for (let i = 0; i < len; i++) arr.push(arb.generate());
      return arr;
    });
  },
  record(schema) {
    return new Arbitrary(() => {
      const obj = {};
      for (const [key, arb] of Object.entries(schema)) {
        obj[key] = arb.generate();
      }
      return obj;
    });
  },
  property(...args) {
    const fn = args[args.length - 1];
    const arbs = args.slice(0, -1);
    return {
      run(numRuns = 100) {
        for (let i = 0; i < numRuns; i++) {
          const values = arbs.map((a) => a.generate());
          fn(...values);
        }
      }
    };
  },
  asyncProperty(...args) {
    const fn = args[args.length - 1];
    const arbs = args.slice(0, -1);
    return {
      async run(numRuns = 100) {
        for (let i = 0; i < numRuns; i++) {
          const values = arbs.map((a) => a.generate());
          await fn(...values);
        }
      }
    };
  },
  async assert(property, { numRuns = 100 } = {}) {
    await property.run(numRuns);
  }
};

export default fc;
